using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameFrontEnd
{
 const int UnitEvidenceCheckpoints=15;
 async Task UnitEvidenceStep(int n){await Frame();var s=game!.Session;
  if(FlowCase=="evidence-unit"){if(n<=13)await UnitHeldStep(n);if(n==12){var w=s.DiagnosticSnapshot();Check(!NewGameMilitary.ReceiptConfirmedToSender(w,CurrentInquiryReply().ReplyMessage,NewGameMilitary.UnitIdsFor(game!.Session.DiagnosticSnapshot())[0].Value),"distant unit has no physical witness of player receipt");Check(w.NewMilitary!.ReplyRecovery!.Flights.Any(f=>f.Kind==UnitReplyLeg.Retry)&&w.Messaging.Receipts.Count(r=>r.MessageId==CurrentInquiryReply().ReplyMessage)==1,"sender without evidence sends bounded copy without repeating receipt");}if(n==14){game.Advance(s.Seconds+3);Check(s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==CurrentInquiryReply().ReplyMessage)<=3,"unknown recipient receipt does not remove copy bound");}game.Press("save");await WaitSave();game.Refresh();return;}
  if(n<=8){await UnitCommandStep(n);return;}
  if(n==9){game.Advance(s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Check(w.Messaging.Receipts.Count(r=>r.MessageId==OriginalCommand().Message)==1&&!MessageFlow.Knows(w.Messaging,OriginalCommandLate().ReplyMessage!,w.PlayerControl.Value),"recipient has actual original but sender has not received acknowledgement");Check(game.OffersMilitary(NewMilitaryAction.RetryRecallHome),"actual visible retry option does not disappear from hidden recipient receipt");if(FlowCase=="evidence-copy")game.ChooseMilitary(NewMilitaryAction.RetryRecallHome);else{var home=NewGameMilitary.Home(w,0);game.ExercisePersonalMove(new(home.X+10000,home.Y));}}
  if(n==10){if(FlowCase=="evidence-copy"){game.Advance(s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last().DueAt);var w=s.DiagnosticSnapshot();Check(w.NewMilitary!.Orders.Count(o=>o.Id.Value.StartsWith("order:unit-post/"))==1&&w.Messaging.Receipts.Count(r=>r.MessageId==OriginalCommand().Message)==1,"duplicate physically arrives with one order effect and formal receipt");}else{game.Advance(OriginalCommandLate().DueAt);game.Advance(Math.Max(s.Seconds,PersonalEnd()+1));Check(!MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,OriginalCommandLate().ReplyMessage!,s.PlayerControl.Value)&&game.OffersMilitary(NewMilitaryAction.RetryRecallHome),"missed acknowledgement does not manufacture sender receipt evidence");}}
  if(n==11&&FlowCase=="evidence-quote"){game.ChooseMilitary(NewMilitaryAction.InquireUnitHome);game.Advance(CurrentInquiry().DueAt);}
  if(n==12){if(FlowCase=="evidence-quote"){game.Advance(CurrentInquiryReply().ReplyDueAt);Check(!MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,OriginalCommandLate().ReplyMessage!,s.PlayerControl.Value),"old acknowledgement remains physically unreceived");}Check(!game.OffersMilitary(NewMilitaryAction.RetryRecallHome),"actual visible retry option stops only after received acknowledgement or quoted receipt proof");}
  if(n==13){game.ChooseMilitary(NewMilitaryAction.PersonalHome);game.Advance(PersonalEnd()+1);game.ChooseMilitary(NewMilitaryAction.Attach);game.ChooseMilitary(NewMilitaryAction.Reclaim);game.ChooseMilitary(NewMilitaryAction.Enter);game.ChooseMilitary(NewMilitaryAction.Unload);game.ChooseMilitary(NewMilitaryAction.Report);game.ChooseMilitary(NewMilitaryAction.Return);}
  if(n==14){game.Advance(s.Seconds+3);OpenAllServiceLetters();Check(s.DiagnosticSnapshot().NewMilitary!.Events.Any(e=>e.Effect==MilitaryEffect.Returned),"same actual person completes military handover after evidence-based retry");game.Press("military-frame");}
  game.Press("save");await WaitSave();game.Refresh();
 }
 async Task BeginUnitEvidenceContinuation(){for(int n=1;n<=7;n++)await MilitaryStep(n);for(int n=0;n<UnitEvidenceCheckpoints;n++){await UnitEvidenceStep(n);game!.SaveCheckpoint("unitevidence"+n);await Capture("s"+n,true);}await Capture("final",true);}
 async Task RestoreUnitEvidence(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,r=>r.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<UnitEvidenceCheckpoints;n++){game!.LoadCheckpoint("unitevidence"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"actual sender/evidence/duplicate carrier pose restored at"+n);await Capture("restored-s"+n,true);for(int next=n+1;next<UnitEvidenceCheckpoints;next++)await UnitEvidenceStep(next);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same actor-known receipt and bounded-copy future from"+n);await Capture("continued-s"+n,true);GD.Print("UNIT_EVIDENCE_RESTORED "+n);}}
 async Task RunUnitEvidenceChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreUnitEvidence();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--unit-evidence-film")){game!.LoadCheckpoint("unitevidence8");game.Press("auto");string dir=Path.Combine(TestOutput,"film");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"evidence-"+n.ToString("D3")+".png"));}game.Press("pause");}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("UNIT_EVIDENCE_PASSED "+FlowCase);}
}
